document.getElementById('registerForm').classList.add('hidden');
document.getElementById('loginForm').classList.remove('hidden');

// Limpa os campos do formulário de login
document.getElementById('username').value = '';
document.getElementById('password').value = '';
}

async function handleActivation() {
const username = sessionStorage.getItem('tempUsername');
const password = sessionStorage.getItem('tempPassword');
console.log('Tentando recuperar credenciais:', { username, password }); // Verifica se as credenciais foram recuperadas
const activationCode = document.getElementById('activationCode').value;

if (!username || !password) {
alert('Erro: Informações de login não encontradas. Por favor, faça login novamente.');
showLoginForm();
return;
}

try {
const response = await fetch('regenerate_key.php', {
method: 'POST',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify({ username, password, activationCode }),
});


const result = await response.json();

if (result.success) {
  localStorage.setItem('hashedAccessKey', result.newHashedAccessKey);
  sessionStorage.removeItem('tempUsername');
  sessionStorage.removeItem('tempPassword');
  alert('Conta ativada com sucesso!');
  redirectTo('index.php');
} else {
  alert(result.message);
}
} catch (error) {
alert('Erro na ativação: ' + error.message);
}
}

